    boardSeats: ["Fnac Darty", "Prisa"],
    notableInvestments: [{ name: "Palantir", ticker: "PLTR" }, { name: "Submer", ticker: null }, { name: "Wefox", ticker: null }, { name: "Shift Technology", ticker: null }, { name: "Bolttech", ticker: null }],
    ipoCount: null,
